const response = $input.first().json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text;

let fundRiskSummary = null;
if (text) {
  try {
    const cleaned = text.replace(/^```json\n?|```$/gm, '').trim();
    fundRiskSummary = JSON.parse(cleaned);
  } catch (e) {
    console.warn('CR-05: Could not parse Gemini response as JSON.');
  }
}

if (!fundRiskSummary) {
  fundRiskSummary = { raw_response: response, extraction_failed: true };
}

const caseData = $('Postgres: Aggregate DD Inputs').first().json;

return [{
  json: {
    ...caseData,
    fund_risk_summary: fundRiskSummary,
    cr05_raw_response: response
  }
}];

// Non-fund path: pass case data through with null fund_risk_summary
const caseData = $input.first().json;
return [{
  json: {
    ...caseData,
    fund_risk_summary: null,
    cr05_raw_response: null
  }
}];

// Merge fund and non-fund branches into a single item for CR-03
// Both branches emit the same shape; just pass through.
return [$input.first()];

