const response = $input.first().json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text;

let ddReport = null;
if (text) {
  try {
    const cleaned = text.replace(/^```json\n?|```$/gm, '').trim();
    ddReport = JSON.parse(cleaned);
  } catch (e) {
    throw new Error('CR-03: Failed to parse Gemini response as JSON. Raw text: ' + text.slice(0, 500));
  }
}

if (!ddReport) {
  throw new Error('CR-03: No text in Gemini response. Raw response: ' + JSON.stringify(response).slice(0, 500));
}

const caseData = $('Code: Merge Branches').first().json;

const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const reportPath = `/Applicants/${caseData.applicant_id}/06_DD_Report/dd_report_${ts}.md`;
const reportJsonPath = `/Applicants/${caseData.applicant_id}/06_DD_Report/dd_report_${ts}.json`;

const riskBadge = {
  'Low': 'ðŸŸ¢ LOW',
  'Medium': 'ðŸŸ¡ MEDIUM',
  'High': 'ðŸ”´ HIGH',
  'Decline': 'â›” DECLINE'
}[ddReport.risk_rating] || ddReport.risk_rating;

const decisionBadge = {
  'Proceed': 'âœ… PROCEED',
  'Proceed with Conditions': 'âš ï¸ PROCEED WITH CONDITIONS',
  'Decline': 'âŒ DECLINE'
}[ddReport.recommended_decision] || ddReport.recommended_decision;

const mdReport = `# Due Diligence Report

**Case ID:** ${caseData.case_id}
**Applicant:** ${caseData.applicant_name}
**Applicant Type:** ${caseData.applicant_type}
**Generated:** ${new Date().toISOString()}
**Model:** gemini-2.5-flash (CR-03)

---

## Risk Rating: ${riskBadge}

## Recommended Decision: ${decisionBadge}

---

## Executive Summary

${ddReport.executive_summary}

---

## Fit and Proper Assessment

${ddReport.fit_and_proper_assessment}

${ddReport.fund_specific_findings ? `## Fund-Specific Findings\n\n${ddReport.fund_specific_findings}\n\n---` : ''}

## Red Flags

${ddReport.red_flags.length > 0 ? ddReport.red_flags.map(f => `- ${f}`).join('\n') : '_None identified._'}

## Orange Flags

${ddReport.orange_flags.length > 0 ? ddReport.orange_flags.map(f => `- ${f}`).join('\n') : '_None identified._'}

## Outstanding Items

${ddReport.outstanding_items.length > 0 ? ddReport.outstanding_items.map(i => `- ${i}`).join('\n') : '_None._'}

${ddReport.conditions && ddReport.conditions.length > 0 ? `## Conditions\n\n${ddReport.conditions.map((c, i) => `${i+1}. ${c}`).join('\n')}\n\n---` : ''}

## Rationale

${ddReport.rationale}

---

_This report was generated automatically by Alpha Node's DD AI system. It must be reviewed and approved by a qualified senior officer before any decision is acted upon._
`;

return [{
  json: {
    ...caseData,
    dd_report: ddReport,
    cr03_raw_response: response,
    report_markdown: mdReport,
    report_path: reportPath,
    report_json_path: reportJsonPath,
    report_timestamp: ts,
    input_token_count: response.usageMetadata?.promptTokenCount || null,
    output_token_count: response.usageMetadata?.candidatesTokenCount || null
  }
}];

