  || slackResponse?.user?.name 
  || slackResponse?.approved_by 
  || 'unknown';

console.log('WF-07-C: Slack decision received:', decision, 'by', approvedBy);

const caseData = $('Code: Extract & Render CR-03').item.json;

return [{
  json: {
    ...caseData,
    slack_decision: decision,
    decision_made_by: approvedBy,
    decision_made_at: new Date().toISOString()
  }
}];
